// ============================================================================
// C&R ESG 참여자 명단 — 동적 SVG 엔드포인트 (Figma 디자인 적용판)
// 배치: cnr-esg/functions/api/roster.ts  →  https://esg.cnrres.store/api/roster
// 그룹웨어 공지: <a href="..."><img src="https://esg.cnrres.store/api/roster"></a>
//
// 디자인 출처: Figma node 1440:35 (하늘·초원·나무 배경 + 흰 카드 그리드 + 하늘색 CTA)
//  - 배경 사진은 base64 인라인(<img> 임베드 SVG는 외부 이미지 차단 → data: URI만 가능)
//  - 메인페이지 동일 RPC(get_main_item_donors/get_main_money_donors) → 명단 SSOT
//  - is_anonymous=true 는 "익명"으로 마스킹(이름·부서 비노출)
//  - Cache-Control: no-store → 공지 열 때마다 최신
//  - 한글은 시스템 폰트(맑은 고딕). 스크립트/외부리소스 0.
// ============================================================================

const W = 1200;
const PADX = 56;
const COLS = 4;
const GAPX = 16;
const GAPY = 28;
const COLW = (W - PADX * 2 - GAPX * (COLS - 1)) / COLS;   // 260
const CARDH = 80;

// 디자인 좌표(viewBox)는 1200 기준 그대로, 렌더 박스만 70%로 축소 → 디자인 불변, 표시만 작게
const SCALE = 0.7;

// Figma 배경(1000x1250, 최적화 JPEG) — data URI 인라인
const BG = "data:image/jpeg;base64,";

// ── 진입점 ──────────────────────────────────────────────────────────────────
export async function onRequestGet(context) {
  const env = (context && context.env) || {};
  const SUPABASE_URL =
    env.SUPABASE_URL || env.VITE_SUPABASE_URL ||
    "https://jjzcqpbwkkujttwxksvy.supabase.co";
  const SUPABASE_ANON_KEY = env.SUPABASE_ANON_KEY || env.VITE_SUPABASE_ANON_KEY;

  let items = [];
  let monies = [];
  let errMsg = "";
  try {
    if (!SUPABASE_ANON_KEY) throw new Error("ENV_MISSING:ANON_KEY");
    const [a, b] = await Promise.all([
      callRpc(SUPABASE_URL, SUPABASE_ANON_KEY, "get_main_item_donors"),
      callRpc(SUPABASE_URL, SUPABASE_ANON_KEY, "get_main_money_donors"),
    ]);
    items = Array.isArray(a) ? a : [];
    monies = Array.isArray(b) ? b : [];
  } catch (e) {
    errMsg = String((e && e.message) ? e.message : e);
  }

  const svg = errMsg ? renderError(errMsg) : renderRoster(items, monies);
  return new Response(svg, {
    headers: {
      "Content-Type": "image/svg+xml; charset=utf-8",
      "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
      "Pragma": "no-cache",
      "Access-Control-Allow-Origin": "*",
    },
  });
}

async function callRpc(baseUrl, anonKey, fn) {
  const res = await fetch(`${baseUrl}/rest/v1/rpc/${fn}`, {
    method: "POST",
    headers: {
      "apikey": anonKey,
      "Authorization": `Bearer ${anonKey}`,
      "Content-Type": "application/json",
    },
    body: "{}",
  });
  if (!res.ok) throw new Error(`${fn}:${res.status}`);
  return await res.json();
}

// ── 명단 렌더 (Figma 레이아웃) ──────────────────────────────────────────────
function renderRoster(items, monies) {
  const head =
    `  <text class="title" x="${PADX}" y="112">함께해주신 분들</text>\n` +
    `  <text class="sub" x="${PADX}" y="150">C&amp;R 29주년 ESG 나무심기, 모두의 참여로 만들어갑니다.</text>\n` +
    `  <line x1="${PADX}" y1="178" x2="${W - PADX}" y2="178" stroke="#ffffff" stroke-opacity="0.55" stroke-width="1.5"/>`;

  const sec1 = buildSection("바자회 물품 기부 참여", items, 218);
  const sec2 = buildSection("금액 기부자", monies, sec1.endY + 20);

  const footY = sec2.endY + 48;
  const stamp = kstStamp();

  const ctaText = "바자회 물품 기부하러 가기";
  const ctaW = ctaText.length * 24 + 96;
  const ctaH = 76;
  const ctaY = footY + 28;
  const ctaX = Math.round((W - ctaW) / 2);
  const H = ctaY + ctaH + 180;   // CTA 아래로 THANK YOU(배경) 노출 여백

  const body =
    head + "\n" +
    sec1.svg + "\n" +
    sec2.svg + "\n" +
    `  <text class="foot" x="${W / 2}" y="${footY}" text-anchor="middle">마지막 업데이트 ${stamp} KST · 공지를 새로 열 때마다 자동 갱신됩니다</text>\n` +
    `  <rect x="${ctaX}" y="${ctaY}" width="${ctaW}" height="${ctaH}" rx="22" fill="#90D1ED"/>\n` +
    `  <text class="cta" x="${W / 2}" y="${ctaY + ctaH / 2 + 9}" text-anchor="middle">${esc(ctaText)}</text>`;

  return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="${Math.round(W * SCALE)}" height="${Math.round(H * SCALE)}" viewBox="0 0 ${W} ${H}">
  <style>
    text{font-family:'Malgun Gothic','Apple SD Gothic Neo','\ub9d1\uc740 \uace0\ub515','Noto Sans KR',sans-serif;}
    .title{font-size:56px;font-weight:300;fill:#ffffff;}
    .sub{font-size:20px;font-weight:500;fill:#ffffff;}
    .sec{font-size:24px;font-weight:500;fill:#ffffff;}
    .cnt{font-size:15px;font-weight:400;fill:#ffffff;fill-opacity:0.85;}
    .nm{font-size:22px;font-weight:600;fill:#111111;letter-spacing:0.4px;}
    .dp{font-size:13px;font-weight:400;fill:#5a5a5a;}
    .foot{font-size:18px;font-weight:400;fill:#ffffff;}
    .cta{font-size:24px;font-weight:600;fill:#ffffff;}
    .empty{font-size:15px;fill:#ffffff;fill-opacity:0.85;}
  </style>
  <image xlink:href="${BG}" href="${BG}" x="0" y="0" width="${W}" height="${H}" preserveAspectRatio="xMidYMax slice"/>
${body}
</svg>`;
}

function buildSection(title, donors, startY) {
  let s = `  <text class="sec" x="${PADX}" y="${startY + 20}">${esc(title)} <tspan class="cnt">${donors.length}\uba85</tspan></text>`;
  const gridY = startY + 46;
  if (donors.length === 0) {
    s += `\n  <text class="empty" x="${PADX}" y="${gridY + 22}">\uc544\uc9c1 \ucc38\uc5ec\uc790\uac00 \uc5c6\uc2b5\ub2c8\ub2e4</text>`;
    return { svg: s, endY: gridY + 44 };
  }
  for (let i = 0; i < donors.length; i++) {
    const col = i % COLS;
    const row = Math.floor(i / COLS);
    const x = PADX + col * (COLW + GAPX);
    const y = gridY + row * (CARDH + GAPY);
    s += "\n" + card(donors[i], x, y);
  }
  const rows = Math.ceil(donors.length / COLS);
  const endY = gridY + rows * CARDH + (rows - 1) * GAPY;
  return { svg: s, endY };
}

function card(d, x, y) {
  const anon = !!(d && d.is_anonymous);
  const name = anon ? "\uc775\uba85" : ((d && d.donor_name) || "\uc775\uba85");
  const dept = anon ? "" : ((d && d.donor_dept) || "");
  let g = `  <rect x="${x}" y="${y}" width="${COLW}" height="${CARDH}" rx="16" fill="#ffffff"/>`;
  if (dept) {
    g += `\n  <text class="nm" x="${x + 18}" y="${y + 36}">${esc(trunc(name, 10))}</text>`;
    g += `\n  <text class="dp" x="${x + 18}" y="${y + 58}">${esc(trunc(dept, 16))}</text>`;
  } else {
    g += `\n  <text class="nm" x="${x + 18}" y="${y + CARDH / 2 + 8}">${esc(trunc(name, 10))}</text>`;
  }
  return g;
}

function renderError(msg) {
  const safe = String(msg).replace(/--+/g, "-");
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="200" viewBox="0 0 ${W} 200">
  <style>text{font-family:'Malgun Gothic','Apple SD Gothic Neo',sans-serif;}</style>
  <rect width="${W}" height="200" fill="#9CC9E6"/>
  <text x="${PADX}" y="96" font-size="40" font-weight="300" fill="#ffffff">\ud568\uaed8\ud574\uc8fc\uc2e0 \ubd84\ub4e4</text>
  <text x="${PADX}" y="132" font-size="16" fill="#ffffff">\uba85\ub2e8\uc744 \uc900\ube44\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc7a0\uc2dc \ud6c4 \ub2e4\uc2dc \ud655\uc778\ud574 \uc8fc\uc138\uc694.</text>
  <!-- ${esc(safe)} -->
</svg>`;
}

function kstStamp() {
  const d = new Date(Date.now() + 9 * 3600 * 1000);
  const p = (n) => String(n).padStart(2, "0");
  return `${d.getUTCFullYear()}.${p(d.getUTCMonth() + 1)}.${p(d.getUTCDate())} ${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`;
}

function trunc(s, n) {
  s = String(s == null ? "" : s);
  return s.length > n ? s.slice(0, n - 1) + "\u2026" : s;
}

function esc(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

export { renderRoster, renderError };
